  gen("c11-3.height", 4, [[10, 20], [20, 45, 80]], (u, H) => { const t = Math.sqrt(2 * H / 10); return { q: `A ball is thrown horizontally at ${u} m/s from a cliff ${H} m high. How far from the base does it land? (g = 10 m/s²)`, v: u * t, u: "m", w: [u * u / 10, u * Math.sqrt(H / 10), H], e: "Fall time depends only on height; horizontal distance = speed × time.", steps: [`t = √(2H/g) = √(2 × ${H}/10) = ${sig(t)} s`, `x = u × t = ${u} × ${sig(t)} = ${sig(u * t)} m`], c: "projectile motion" }; });
  gen("c11-4.pulley", 4, [[2, 3, 5], [1, 2]], (m1, m2) => { const a = (m1 - m2) * 10 / (m1 + m2), T = 2 * m1 * m2 * 10 / (m1 + m2); return m1 === m2 ? { q: `Two ${m1} kg masses hang over a frictionless pulley. What is their acceleration?`, v: 0.001, u: "m/s²", fmt: x => x < 0.01 ? "0" : sig(x), w: [10, 5, 2.5], e: "Equal masses balance.", c: "Newton's second law" } : { q: `Masses of ${m1} kg and ${m2} kg hang over a light frictionless pulley (Atwood machine). Find the acceleration. (g = 10 m/s²)`, v: a, u: "m/s²", w: [10, (m1 - m2) * 10 / m1, T / m1], e: `a = (m₁ − m₂)g/(m₁ + m₂). The string tension is ${sig(T)} N.`, steps: [`net pull = (${m1} − ${m2}) × 10 = ${(m1 - m2) * 10} N`, `total mass = ${m1 + m2} kg`, `a = ${sig(a)} m/s²`], c: "Newton's second law" }; });
  gen("c11-5.spring", 4, [[100, 200, 500], [0.05, 0.1, 0.2], [0.1, 0.5]], (kk, x, m) => ({ q: `A spring (k = ${kk} N/m) compressed by ${x} m launches a ${m} kg ball on a smooth floor. Find the ball's speed.`, v: x * Math.sqrt(kk / m), u: "m/s", w: [kk * x / m, 0.5 * kk * x * x], e: "Spring energy ½kx² becomes kinetic energy ½mv².", steps: [`½kx² = ${sig(0.5 * kk * x * x)} J`, `v = x√(k/m) = ${sig(x * Math.sqrt(kk / m))} m/s`], c: "potential energy" }));
  gen("c11-5.coll", 3, [[1, 2, 4], [2, 6], [1, 2, 3]], (m1, u1, m2) => { const v1 = (m1 - m2) / (m1 + m2) * u1, v2 = 2 * m1 / (m1 + m2) * u1; return { q: `A ${m1} kg ball at ${u1} m/s hits a stationary ${m2} kg ball head-on in a perfectly elastic collision. Find the second ball's speed afterwards.`, v: v2, u: "m/s", w: [m1 * u1 / (m1 + m2), u1, Math.abs(v1)], e: `v₂ = 2m₁u₁/(m₁ + m₂). The first ball ends with ${sig(v1)} m/s.`, c: "momentum" }; });
  gen("c11-6.rpm", 1, [[30, 60, 120, 600, 3000]], r => ({ q: `A wheel spins at ${r} revolutions per minute. What is its angular speed?`, v: r * 2 * PI / 60, u: "rad/s", w: [r / 60, r * 2 * PI], e: "ω = 2π × (rev per second).", c: "angular momentum" }));
  gen("c11-6.KE", 2, [[0.5, 1, 2, 5], [5, 10, 20]], (I, w) => ({ q: `A flywheel with I = ${I} kg m² spins at ${w} rad/s. Find its rotational kinetic energy.`, v: 0.5 * I * w * w, u: "J", w: [I * w * w, 0.5 * I * w], e: "K = ½Iω², the rotating version of ½mv².", c: "moment of inertia" }));
  gen("c11-6.seesaw", 2, [[20, 30, 40], [1, 1.5, 2], [25, 50, 60]], (m1, d1, m2) => ({ q: `On a see-saw, a ${m1} kg child sits ${d1} m from the pivot. Where must a ${m2} kg child sit to balance?`, v: m1 * d1 / m2, u: "m from the pivot", w: [m2 * d1 / m1, d1], e: "Balance when torques match: m₁d₁ = m₂d₂.", c: "torque" }));
  gen("c11-6.roll", 4, [[["solid sphere", 0.4], ["disc", 0.5], ["ring", 1]], [1, 2, 5]], (b, hh) => ({ q: `A ${b[0]} rolls without slipping from rest down a ${hh} m high slope. Find its speed at the bottom. (g = 10 m/s²)`, v: Math.sqrt(2 * 10 * hh / (1 + b[1])), u: "m/s", w: [Math.sqrt(20 * hh), Math.sqrt(10 * hh)], e: "mgh = ½mv²(1 + k²/R²). Some energy goes into spinning, so rolling objects are slower than sliding ones. The sphere wins the race!", steps: [`k²/R² = ${b[1]}`, `v = √(2gh/(1 + ${b[1]})) = ${sig(Math.sqrt(2 * 10 * hh / (1 + b[1])))} m/s`], c: "moment of inertia" }));
  gen("c11-7.satE", 4, [[500, 1000, 5000], [100, 1000]], (hk, m) => { const r = RE + hk * 1e3, E = -MU * m / (2 * r); return { q: `Find the total energy of a ${m} kg satellite in a circular orbit ${hk} km above Earth. (GM = 3.986 × 10¹⁴ m³/s²)`, v: E / 1e9, u: "GJ", w: [-MU * m / r / 1e9, MU * m / (2 * r) / 1e9], fmt: x => sig(x), e: "E = −GMm/2r. Negative means bound. KE = +GMm/2r, PE = −GMm/r.", c: "orbital speed" }; });
