  gen("c11-8.U", 3, [[100, 200, 500], [1, 2, 5]], (F, dL) => ({ q: `A wire stretched elastically by ${dL} mm under a final load of ${F} N stores how much energy?`, v: 0.5 * F * dL * 1e-3, u: "J", w: [F * dL * 1e-3, F * dL], e: "U = ½ × force × extension (the area under the force–extension line).", c: "stress" }));
