  gen("c11-11.iso", 3, [[1, 2], [300, 400], [2, 3]], (n, T, r) => ({ q: `${n} mol of ideal gas expands isothermally at ${T} K to ${r} times its volume. How much work does it do? (R = 8.314)`, v: n * 8.314 * T * Math.log(r), u: "J", w: [n * 8.314 * T * (r - 1), n * 8.314 * T], e: "W = nRT ln(V₂/V₁). ΔU = 0, so Q = W.", c: "work" }));
