  gen("c11-12.ratio2", 3, [[["hydrogen", 2], ["helium", 4]], [["oxygen", 32], ["nitrogen", 28], ["carbon dioxide", 44]]], (a, b) => ({ q: `At the same temperature, how many times faster (rms) are ${a[0]} molecules than ${b[0]} molecules?`, v: Math.sqrt(b[1] / a[1]), u: "×", w: [b[1] / a[1], Math.sqrt(a[1] / b[1])], e: "v_rms ∝ 1/√M at a fixed temperature.", c: "temperature" }));
  gen("c11-12.escape", 4, [[["the Moon", 2380, 390], ["Mars", 5030, 300], ["Earth", 11200, 1000], ["Jupiter", 59500, 1000]], [["hydrogen", 0.002], ["helium", 0.004], ["nitrogen", 0.028]]], (p, g) => { const T = p[2], v = Math.sqrt(3 * 8.314 * T / g[1]), keep = v < p[1] / 6; return pickQ({ q: `On ${p[0]} (escape speed ${p[1] / 1000} km/s; gas at the top of the atmosphere ≈ ${T} K), can ${g[0]} stay in the atmosphere for billions of years? (Rule of thumb: yes if v_rms < 1/6 of escape speed)`, right: keep ? "Yes, it can be held" : "No, it slowly escapes", pool: ["Yes, it can be held", "No, it slowly escapes"], e: `v_rms = √(3RT/M) ≈ ${Math.round(v)} m/s vs 1/6 escape ≈ ${Math.round(p[1] / 6)} m/s. Escape happens at the very top of the atmosphere, which is much hotter than the ground. That is why Jupiter keeps hydrogen while Earth keeps losing hydrogen and helium.`, c: "escape velocity" }); });
