  gen("c12-1.null", 4, [[1, 4, 9], [4, 9, 16], [0.3, 0.6, 1]], (q1, q2, d) => { if (q1 === q2) q2 = q2 * 4; const x = d * Math.sqrt(q1) / (Math.sqrt(q1) + Math.sqrt(q2)); return { q: `Like charges of ${q1} μC and ${q2} μC are ${d} m apart. How far from the ${q1} μC charge is the electric field zero?`, v: x, u: "m", w: [d / 2, d * q1 / (q1 + q2), d - x], e: "Between like charges the fields oppose. Set kq₁/x² = kq₂/(d − x)². The zero is nearer the smaller charge.", steps: [`√(q₁/q₂) = x/(d − x) = ${sig(Math.sqrt(q1 / q2))}`, `x = d√q₁/(√q₁ + √q₂)`, `x = ${sig(x)} m`], c: "electric field" }; });
