  gen("c12-13.half", 2, [[1000, 800, 6400], [1, 2, 3], [5, 10]], (N0, n, T) => ({ q: `A sample has ${N0} undecayed nuclei and a half-life of ${T} min. How many remain after ${n * T} min?`, v: N0 * Math.pow(0.5, n), w: [N0 / (2 * n), N0 - N0 / (2 * n), N0 * Math.pow(0.5, n + 1)], fmt: x => String(Math.round(x)), e: "N = N₀(½)^(t/T).", c: "half-life" }));
  gen("c12-13.iso", 1, [[["¹²C and ¹⁴C", "isotopes"], ["²H and ³H", "isotopes"], ["¹⁴C and ¹⁴N", "isobars"], ["⁴⁰Ar and ⁴⁰Ca", "isobars"], ["³H and ⁴He", "isotones"], ["¹³C and ¹⁴N", "isotones"]]], x => pickQ({ q: `${x[0]} are best described as...`, right: x[1], pool: ["isotopes", "isobars", "isotones"], e: "Isotopes: same Z. Isobars: same A. Isotones: same number of neutrons.", c: "isotope" }));
  gen("c12-13.mc2", 2, [[1e-3, 1e-6, 1, 0.01, 0.1]], m => ({ q: `If ${m} g of matter were converted completely into energy, how much energy would be released?`, v: m * 1e-3 * 9e16, u: "J", w: [m * 9e16, m * 1e-3 * 3e8], e: "E = mc² with m in kg.", c: "E = mc²" }));
