  gen("c11-13.scale", 2, [[["a pendulum's length", "T ∝ √L"], ["the mass on a spring", "T ∝ √m"]], [2, 4, 9, 16, 0.25]], (s, n) => ({ q: `If ${s[0]} is multiplied by ${n}, its period is multiplied by...`, v: Math.sqrt(n), w: [n, 1 / Math.sqrt(n), n * n], fmt: x => "× " + sig(x), e: `${s[1]}, so the period changes by √${n}.`, c: "simple harmonic motion" }));
  gen("c12-8.use", 1, [[["TV remote controls", "infrared"], ["cancer radiotherapy", "gamma rays"], ["airport luggage scanners", "X-rays"], ["killing germs in water purifiers", "ultraviolet"], ["mobile phone signals", "microwaves"], ["FM radio broadcasts", "radio waves"], ["night-vision cameras", "infrared"], ["microwave ovens", "microwaves"], ["photosynthesis in leaves", "visible light"], ["LASIK eye surgery", "ultraviolet"], ["radar speed guns", "microwaves"], ["imaging broken bones", "X-rays"]]], x => pickQ({ q: `Which part of the electromagnetic spectrum is used for ${x[0]}?`, right: x[1], pool: BANDS, e: "Every band is the same kind of wave. Only the wavelength differs, and that decides what it can do.", c: "electromagnetic spectrum" }));
